function validate([sentence1, sentence2, similarPairs]) {
  const isWord = word => typeof word === 'string' && /^[a-zA-Z]{1,20}$/.test(word);
  if (sentence1.length < 1 || sentence1.length > 1000 || sentence2.length < 1 || sentence2.length > 1000) return 'Each sentence has 1 to 1000 words.';
  if (!sentence1.every(isWord) || !sentence2.every(isWord)) return 'Each word has 1 to 20 English letters.';
  if (similarPairs.length > 1000) return 'similarPairs has at most 1000 pairs.';
  const listed = new Set();
  for (const pair of similarPairs) {
    if (pair.length !== 2 || !pair.every(isWord)) return 'Each pair holds two words of 1 to 20 English letters.';
    const key = pair[0] + ' ' + pair[1];
    if (listed.has(key)) return 'The pairs in similarPairs must be distinct.';
    listed.add(key);
  }
  return null;
}

