function areSentencesSimilar(sentence1, sentence2, similarPairs) {
  if (sentence1.length !== sentence2.length) {
    return false;
  }
  const similar = new Set();
  for (const [x, y] of similarPairs) {
    similar.add(x + '#' + y);
    similar.add(y + '#' + x);
  }
  for (let i = 0; i < sentence1.length; i++) {
    const first = sentence1[i];
    const second = sentence2[i];
    if (first === second) {
      continue;
    }
    if (!similar.has(first + '#' + second)) {
      return false;
    }
  }
  return true;
}

