function areSentencesSimilar(sentence1, sentence2, similarPairs) {
  // Scan the whole pair list for every position instead of building a lookup table.
  if (sentence1.length !== sentence2.length) return false;
  return sentence1.every((word, i) => {
    const other = sentence2[i];
    if (word === other) return true;
    return similarPairs.some(([x, y]) => (x === word && y === other) || (x === other && y === word));
  });
}

