function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const large = size === 'large';
  const letters = large ? 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ' : 'abA';
  const vocabularySize = large ? 400 : 2 + pick(4);
  const vocabulary = [];
  const known = new Set();
  while (vocabulary.length < vocabularySize) {
    const length = large ? 1 + pick(20) : 1 + pick(2);
    let word = '';
    for (let i = 0; i < length; i++) word += letters[pick(letters.length)];
    if (!known.has(word)) { known.add(word); vocabulary.push(word); }
  }
  const randomWord = () => vocabulary[pick(vocabulary.length)];
  // Distinct ordered pairs, a word may even be paired with itself.
  const wanted = Math.min(large ? 1000 : pick(6), vocabularySize * vocabularySize);
  const pairs = [];
  const listed = new Set();
  for (let attempt = 0; pairs.length < wanted && attempt < 100000; attempt++) {
    const x = randomWord(), y = randomWord();
    if (listed.has(x + ' ' + y)) continue;
    listed.add(x + ' ' + y);
    pairs.push([x, y]);
  }
  const partners = word => pairs.filter(([x, y]) => x === word || y === word).map(([x, y]) => (x === word ? y : x));
  const length = large ? 1000 : 1 + pick(4);
  const sentence1 = Array.from({ length }, randomWord);
  const sentence2 = sentence1.map(word => {
    const options = partners(word);
    const roll = rand();
    if (roll < 0.3 || options.length === 0) return large || roll < 0.9 ? word : randomWord();
    return roll < (large ? 1 : 0.9) ? options[pick(options.length)] : randomWord();
  });
  if (large && rand() < 0.5) sentence2[pick(length)] = randomWord();
  if (!large && rand() < 0.15) {
    if (sentence2.length > 1 && rand() < 0.5) sentence2.pop();
    else sentence2.push(randomWord());
  }
  return rand() < 0.5 ? [sentence1, sentence2, pairs] : [sentence2, sentence1, pairs];
}
